{"nbformat":4,"nbformat_minor":0,"metadata":{"colab":{"provenance":[],"authorship_tag":"ABX9TyN6rCOTPRNWdEQHtR+aEBoa"},"kernelspec":{"name":"python3","display_name":"Python 3"},"language_info":{"name":"python"}},"cells":[{"cell_type":"code","execution_count":null,"metadata":{"id":"AYidOQrKGcMv"},"outputs":[],"source":["from torch import nn\n","\n","class Autoencoder(nn.Module):\n","  def __init__(self, input_dim, latent_dim):\n","    super().__init__()\n","\n","    self.encoder = nn.Sequential(\n","      nn.Linear(input_dim, 256),\n","      nn.ReLU(),\n","      nn.Linear(256, 128),\n","      nn.ReLU(),\n","      nn.Linear(128, latent_dim))\n","\n","    self.decoder = nn.Sequential(\n","      nn.Linear(latent_dim, 128),\n","      nn.ReLU(),\n","      nn.Linear(128, 256),\n","      nn.ReLU(),\n","      nn.Linear(256, input_dim))\n","\n","    def forward(self, x):\n","      z = self.encoder(x)\n","      reconstruction = self.decoder(z)\n","      return reconstruction\n","\n","    def fit(self, X, epochs=100, lr=0.001):\n","        X_tensor = torch.FloatTensor(X)\n","\n","        criterion = nn.MSELoss()\n","        optimizer = optim.Adam(self.parameters(), lr=lr)\n","\n","        self.train()\n","        for epoch in range(epochs):\n","            optimizer.zero_grad()\n","\n","            reconstruction = self(X_tensor)\n","            loss = criterion(reconstruction, X_tensor)\n","\n","            loss.backward()\n","            optimizer.step()\n","\n","        return self\n","\n","    def transform(self, X):\n","        self.eval()\n","\n","        with torch.no_grad():\n","            X_tensor = torch.FloatTensor(X)\n","            latent = self.encoder(X_tensor)\n","\n","        return latent.numpy()"]}]}